contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that will be called by the checker
    function run(uint256 seedMarketDrugs) public payable {
        require(true);

        // Seed the market with some initial drugs so contract becomes initialized.
        // seedMarket requires marketDrugs==0; fresh deployment satisfies that.
        c.seedMarket{value: 0}(seedMarketDrugs);

        // Ensure the caller (this contract) currently has zero kilos via the public getter
        // If it's not zero, the precondition of getFreeKilo would revert, so we only proceed when it's zero.
        // We observe it and then call getFreeKilo.
        uint256 kilosBefore = c.getMyKilo();
        // must be zero to satisfy getFreeKilo requirement; if not, the invocation below would revert
        // but we still execute it inside a try/catch to record whether it reverted.
        bool reverted;
        try c.getFreeKilo() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-call observable values
        uint256 kilosAfter = c.getMyKilo();
        uint256 drugsToProduce = c.DRUGS_TO_PRODUCE_1KILO();
        uint256 startingKilos = c.STARTING_KILOS();

        // getDrugsSinceLastCollect returns number of drugs produced since lastCollect; it's bounded by DRUGS_TO_PRODUCE_1KILO * Kilos
        uint256 drugsSince = c.getDrugsSinceLastCollect(address(this));

        // The general rule we assert:
        // If getFreeKilo did not revert and previously kilosBefore was zero, then:
        //  - kilosAfter >= startingKilos (we expect it sets to STARTING_KILOS)
        //  - drugsSince <= DRUGS_TO_PRODUCE_1KILO * kilosAfter (the implementation uses min with DRUGS_TO_PRODUCE_1KILO)
        assert((reverted || kilosBefore != 0) || (kilosAfter >= startingKilos && drugsSince <= drugsToProduce * kilosAfter));
    }

    // receive is not needed but provided so the test contract can accept ETH if necessary
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: caller supplies seed amount, buy amount, and a referral address
    function run(uint256 seedDrugs, uint256 buyAmountWei, address ref) public payable {
        require(address(this).balance >= buyAmountWei, "need balance for buy");
        // 1) seed the market so contract becomes initialized (only works once, fresh c provided by harness)
        c.seedMarket{value: 0}(seedDrugs);

        // 2) record pre-state visible through public surface
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeClaimed = c.claimedDrugs(address(this));

        // 3) try to buy drugs with specified wei amount; capture whether it reverted
        bool reverted;
        try c.buyDrugs{value: buyAmountWei}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // 4) read post-state
        uint256 afterContractBalance = address(c).balance;
        uint256 afterClaimed = c.claimedDrugs(address(this));

        // general rule: if buyDrugs did not revert and buyAmountWei>0 then contract balance increased by at least buyAmountWei,
        // and caller's claimedDrugs increased (or at least is not less) compared to before, by an amount equal to calculateDrugBuySimple(msg.value) minus devFee;
        // We cannot call c.calculateDrugBuySimple(msg.value) with msg.value, so we express that if the call succeeded then afterClaimed >= beforeClaimed.
        // Also ensure the contract balance increased by at least buyAmountWei when call succeeded (it may forward fee to ceo but balance includes remaining)

        assert(
            reverted
            || (buyAmountWei == 0 ? afterContractBalance >= beforeContractBalance && afterClaimed >= beforeClaimed
                : (afterContractBalance >= beforeContractBalance + buyAmountWei && afterClaimed >= beforeClaimed))
        );
    }

    receive() external payable {}
}
